<template>
 <div class="launcher-editor-preview" :data-shortcut-drag="gesture?'active':undefined" @pointermove="movePointer" @pointerup="finishPointer" @pointercancel="cancel" @lostpointercapture="cancel">
  <div class="launcher-preview-heading"><strong>{{t('首页快捷入口','Home shortcuts')}}</strong><span>{{ids.length}} / {{limit}}</span></div>
  <p class="launcher-editor-instructions" id="launcher-sort-help">{{t('拖动手柄调整顺序，点击 × 移除入口。键盘：空格拿起，方向键移动，回车放下。','Drag a handle to reorder; × removes a shortcut. Keyboard: Space to pick up, arrows to move, Enter to drop.')}}</p>
  <TransitionGroup v-if="ids.length" name="shortcut" tag="div" class="launcher-edit-grid" :style="{gridTemplateColumns:'repeat('+gridColumns+',minmax(0,1fr))'}">
   <div v-for="id in displayed" :key="id" class="launcher-edit-tile" :class="{picked:gesture?.id===id,target:gesture&&displayed.indexOf(id)===gesture.target}" :data-editor-shortcut="id">
    <button type="button" class="launcher-drag-handle" :aria-label="t('移动','Move ')+name(id)" aria-describedby="launcher-sort-help" :aria-pressed="gesture?.id===id" :data-shortcut-handle="id" @pointerdown="startPointer($event,id)" @keydown="key($event,id)"><span aria-hidden="true">⠿</span></button>
    <button type="button" class="launcher-remove" :data-remove-shortcut="id" :aria-label="t('移除','Remove ')+name(id)" :disabled="!!gesture" @click="$emit('remove',id)">×</button>
    <span class="application-icon" :class="resolve(id).tone"><ApplicationArtwork :app="resolve(id)"/></span><strong>{{name(id)}}</strong>
   </div>
  </TransitionGroup>
  <p v-else class="launcher-empty-preview">{{t('从下方添加一个入口，首页就从这里开始。','Add a shortcut below to make this space yours.')}}</p>
  <span class="launcher-sr-only" role="status" aria-live="polite">{{announcement}}</span>
 </div>
</template>
<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue'
import ApplicationArtwork from './ApplicationArtwork.vue'
import {useLauncherCatalog} from './launcherContext'
const {resolveEntry}=useLauncherCatalog()
const props=defineProps<{ids:string[];columns:number;limit:number}>(),emit=defineEmits<{(e:'reorder',ids:string[]):void;(e:'remove',id:string):void}>()
const english=window.vue_lang==='en',t=(zh:string,en:string)=>english?en:zh,resolve=resolveEntry,name=(id:string)=>{const a=resolve(id);return t(a.zh,a.en)}
type Gesture={id:string;origin:string[];target:number;pointer?:number;x:number;y:number;handle?:HTMLElement;slots?:Array<{x:number;y:number;width:number;height:number}>;scrollStart?:number}
const gesture=ref<Gesture|null>(null),announcement=ref(''),gridColumns=computed(()=>Math.max(2,Math.min(4,props.columns)))
const displayed=computed(()=>{if(!gesture.value)return props.ids;const list=gesture.value.origin.filter(id=>id!==gesture.value!.id);list.splice(gesture.value.target,0,gesture.value.id);return list})
let frame=0,lastY=0,scrollBody:HTMLElement|null=null
function stop(){if(frame)cancelAnimationFrame(frame);frame=0;scrollBody=null}
function cancel(){const current=gesture.value;gesture.value=null;stop();if(current?.pointer!==undefined&&current.handle?.hasPointerCapture(current.pointer))current.handle.releasePointerCapture(current.pointer)}
function focus(id:string){void nextTick(()=>{const handle=document.querySelector<HTMLElement>(`[data-shortcut-handle="${CSS.escape(id)}"]`);handle?.focus({preventScroll:true});handle?.scrollIntoView({block:'nearest'})})}
function finish(){const current=gesture.value;if(!current)return;const next=[...displayed.value],changed=next.some((id,i)=>current.origin[i]!==id);cancel();if(changed){emit('reorder',next);announcement.value=name(current.id)+t('已移动到第',' moved to position ')+(next.indexOf(current.id)+1)+t('位','')}focus(current.id)}
function startPointer(event:PointerEvent,id:string){if(event.button!==0||gesture.value)return;event.preventDefault();const handle=(event.currentTarget as HTMLElement).closest<HTMLElement>('.launcher-editor-preview')!;scrollBody=handle.closest('.applications-browser-body');const slots=Array.from(handle.querySelectorAll<HTMLElement>('[data-editor-shortcut]')).map(node=>{const r=node.getBoundingClientRect();return {x:r.x,y:r.y,width:r.width,height:r.height}});gesture.value={id,origin:[...props.ids],target:props.ids.indexOf(id),pointer:event.pointerId,x:event.clientX,y:event.clientY,handle,slots,scrollStart:scrollBody?.scrollTop||0};handle.setPointerCapture(event.pointerId);lastY=event.clientY;frame=requestAnimationFrame(autoScroll)}
// Hit logical slots captured before FLIP animation, not moving DOM tiles.
function locate(x:number,y:number){const current=gesture.value;if(!current?.slots)return;const adjustedY=y+(scrollBody?.scrollTop||0)-(current.scrollStart||0);let distance=Infinity,target=current.target;current.slots.forEach((r,i)=>{const d=((x-r.x-r.width/2)/r.width)**2+((adjustedY-r.y-r.height/2)/r.height)**2;if(d<distance){distance=d;target=i}});current.target=target}
function movePointer(event:PointerEvent){if(event.pointerId!==gesture.value?.pointer)return;lastY=event.clientY;gesture.value.x=event.clientX;gesture.value.y=event.clientY;locate(event.clientX,event.clientY)}
function finishPointer(event:PointerEvent){if(event.pointerId===gesture.value?.pointer)finish()}
function autoScroll(){if(!gesture.value||gesture.value.pointer===undefined)return;if(scrollBody){const box=scrollBody.getBoundingClientRect(),delta=lastY<box.top+36?-8:lastY>box.bottom-36?8:0;if(delta){scrollBody.scrollTop+=delta;locate(gesture.value.x,lastY)}}frame=requestAnimationFrame(autoScroll)}
function key(event:KeyboardEvent,id:string){if(!gesture.value&&[' ','Enter'].includes(event.key)){event.preventDefault();gesture.value={id,origin:[...props.ids],target:props.ids.indexOf(id),x:0,y:0};announcement.value=t('已拿起','Picked up ')+name(id);return}if(gesture.value?.pointer!==undefined||gesture.value?.id!==id)return;if([' ','Enter'].includes(event.key)){event.preventDefault();finish()}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(event.key)){event.preventDefault();const offset=event.key==='ArrowLeft'?-1:event.key==='ArrowRight'?1:event.key==='ArrowUp'?-gridColumns.value:gridColumns.value;gesture.value.target=event.key==='Home'?0:event.key==='End'?props.ids.length-1:Math.max(0,Math.min(props.ids.length-1,gesture.value.target+offset));announcement.value=t('目标位置','Target position ')+(gesture.value.target+1);focus(id)}}
function escape(event:KeyboardEvent){if(event.key==='Escape'&&gesture.value){event.preventDefault();event.stopImmediatePropagation();const id=gesture.value.id;cancel();focus(id)}}
function visibility(){if(document.hidden)cancel()}
watch(()=>props.ids,cancel);watch(()=>props.columns,cancel)
onMounted(()=>{window.addEventListener('keydown',escape,true);window.addEventListener('blur',cancel);window.addEventListener('resize',cancel);document.addEventListener('visibilitychange',visibility)})
onUnmounted(()=>{cancel();window.removeEventListener('keydown',escape,true);window.removeEventListener('blur',cancel);window.removeEventListener('resize',cancel);document.removeEventListener('visibilitychange',visibility)})
</script>
<style scoped>
.launcher-editor-preview{padding:16px;border:1px solid var(--c-line);border-radius:12px;background:var(--c-soft);margin-bottom:24px}.launcher-preview-heading{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:14px}.launcher-preview-heading>span{font-size:12px;color:var(--c-muted);font-variant-numeric:tabular-nums}.launcher-editor-instructions{font-size:12px;line-height:1.7;color:var(--c-muted);margin:8px 0 14px}.launcher-edit-grid{display:grid;gap:10px;position:relative}.launcher-edit-tile{position:relative;min-width:0;min-height:132px;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;gap:7px;padding:38px 6px 10px;box-sizing:border-box;background:var(--c-panel);border:1px solid var(--c-line);border-radius:9px}.launcher-edit-tile>strong{font-size:13px;font-weight:500;text-align:center;line-height:18px;min-height:36px;overflow-wrap:anywhere;max-width:100%}.application-icon{width:36px;height:36px;display:grid;place-items:center;border-radius:10px;background:var(--home-icon-blue-bg);color:var(--home-icon-blue)}.application-icon.teal{background:var(--home-icon-teal-bg);color:var(--home-icon-teal)}.application-icon.violet{background:var(--home-icon-violet-bg);color:var(--home-icon-violet)}.application-icon svg{width:21px;height:21px}.launcher-edit-tile button{position:absolute;top:0;width:44px;height:36px;display:grid;place-items:center;border:0;border-radius:7px;background:transparent;color:var(--c-muted);cursor:pointer;font:22px Arial}.launcher-edit-tile .launcher-drag-handle{left:0;cursor:grab;touch-action:none}.launcher-edit-tile .launcher-remove{right:0}.launcher-edit-tile button:hover{background:var(--c-hover);color:var(--c-text)}.launcher-edit-tile.picked{border-color:var(--c-accent);box-shadow:0 0 0 2px var(--c-accent)}.launcher-edit-tile.picked .launcher-drag-handle{cursor:grabbing;color:var(--c-accent)}.shortcut-move{transition:transform var(--home-motion,140ms) ease}.launcher-empty-preview{font-size:14px;color:var(--c-muted);padding:22px 4px;line-height:1.7}.launcher-sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.launcher-edit-tile button:focus-visible{outline:2px solid var(--c-accent);outline-offset:2px}@media(pointer:coarse){.launcher-edit-tile button{height:44px}.launcher-edit-tile{padding-top:46px;min-height:140px}}@media(max-width:450px){.launcher-editor-preview{padding:12px}.launcher-edit-grid{gap:10px}.launcher-edit-tile>strong{font-size:13px}.launcher-edit-tile button{width:44px}}
</style>
